"""Typed source dossier for the editor/parser shared token-start pointer."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xA029,0xA02B,'data','Inizio dell’ultimo token letto: puntatore condiviso lexer/parser'),(0xAE7F,0xAEA9,'code','Lettore dei token: conserva inizio e avanza secondo la classe'),(0xD9C5,0xDA32,'code','Lexer: salto degli spazi e writer del puntatore al carattere iniziale'),(0xD6CE,0xD714,'code','Preflight lessicale e rifiuto della parola sconosciuta'),(0xD719,0xD769,'code','Seconda scansione lessicale e serializzazione in5B81'),(0xD780,0xD7B2,'code','Parser del giocatore: cursore di ripresa e lista di sintassi'),(0xAAD1,0xAB11,'code','Scansione speculativa del soggetto e ritorno al token'),(0xAB4C,0xAB8E,'code','Gruppi nominali e predicati: rilettura dal token corrente'),(0xB049,0xB09A,'code','Citazione differita: puntatore al contenuto e terminatore temporaneo')]
notes={0xA029:'Word little-endian. D9CD punta ai caratteri5B00; AE82 ai token5B81, anche dentro una citazione. Persistente fra i turni: non è la fine della riga in ogni situazione e non deriva daA028.',0xAE7F:'A02B è il cursore prossimo; non confonderlo con A029 che conserva l’inizio appena letto.',0xAE82:'Writer word dell’inizio del token, anche quando il valore non cambia. A029 è il byte basso; A02A l’alto.',0xAE86:'Classe precedente inA02D: distinta dall’indirizzo iniziale e dal nuovoD.',0xAE8F:'E0,F0 e90 hanno payload di2byte anche se la classe è>=80.',0xAE9B:'Altre classi>=80 occupano1byte; classi<80 occupano3.',0xAEA4:'AvanzaA02B dopo il tipo e l’eventuale payload: questo store non riscriveA029.',0xD9CD:'Dopo il salto degli spazi, conservaHL prima del riconoscimento; può puntare anche aCR o a una parola sconosciuta.',0xD6F5:'La stampa del rifiuto lessicale riparte daA029, prima parola non riconosciuta.',0xD739:'Seconda scansione degli stessi caratteri: serializza le classi e i valori nel buffer dei token.',0xD78B:'A02B inizializzato dal cursore salvatoD6BD; A029 sarà scritto dal lettore, non da questa assegnazione.',0xAB00:'Selezione affermazione: rilegge il primo token non incluso nel soggetto.',0xAB0E:'Fallback dal soggetto speculativo: ripristina il vecchio cursore prossimo.',0xAB4C:'Un gruppo nominale riparte dal token già letto: il puntatore non è dedotto dalla posizione semantica nel comando.',0xB06D:'Salva il cursore al contenuto dopo la virgoletta iniziale nella lista delle citazioni.',0xB085:'Legge fino alla virgoletta finale; i token interni sono già stati consultati dal medesimo writer.',0xB092:'La virgoletta finale puntata daA029 diventaC0 per il parsing differito; il suo indirizzo resta valido.'}
fields={0xA029:[['A029/A02A','word little-endian','Indirizzo iniziale dell’ultima lettura: caratteri per il lexer, token per il parser'],['D9CD','writer lessicale','Primo carattere dopo gli spazi; comprende rifiuti lessicali e fine input'],['AE82','writer sintattico','Prima del tipo e del payload. La scansione nominale può rileggere il medesimo token'],['LOAD','proprietà esplicita','Vecchi salvataggi senza campo restanounknown fino a un writer verificato; non dedurre8A daA028 o dalla registrazione'],['Limiti','protocolli distinti','I comandi di controllo rifiutati dall’oracolo e il controesempioTAKE TO con rollback non sono storie native certificate']]}
lines=['; Dossier offline: dati e istruzioni distinti, riassellati contro il payload.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=min(8,b-at);op='DEFB '+','.join(f'${v:02X}'for v in m[at:at+n])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/parser-token-start';root.mkdir(exist_ok=True);(root/'parser-token-start.asm').write_text('\n'.join(lines)+'\n');(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=149,**({'fields':fields[a]}if a in fields else{}))for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
